-- ============================================================================
-- 03_road_network.sql
-- Intelligent Emergency Response System (IERS)
-- Target: iers_db (iers-postgis container, port 5434)
-- Source: gis/data/campus_roads_export.gpkg → imported_gis_network.json
-- Records: 1282 nodes, 2267 edges
-- ============================================================================
SET search_path TO iers, public;
TRUNCATE iers.vertices_map, iers.incidents, iers.ambulances, iers.hospitals, iers.road_network_edges, iers.road_network_nodes CASCADE;
-- 1. Nodes
ON CONFLICT (node_id) DO NOTHING;
-- 2. Edges
ON CONFLICT (edge_id) DO NOTHING;
-- 3. Hospitals
ON CONFLICT (hospital_id) DO NOTHING;
-- 4. Ambulances
ON CONFLICT (ambulance_id) DO NOTHING;